<script setup>
import { onBeforeUnmount, onMounted, ref } from 'vue';
import PortalLayout from '../layouts/PortalLayout.vue';
import FileUpload from '../components/FileUpload.vue';
import api from '../services/api';
import { useAuthStore } from '../stores/auth';
const auth=useAuthStore(),items=ref([]),announcements=ref([]),managed=ref([]),page=ref(1),total=ref(0),unreadOnly=ref(false),showArchived=ref(false),loading=ref(true),saving=ref(false),error=ref(''),notice=ref('');
const blankDraft=()=>({id:null,title:'',content:'',priority:'NORMAL',audienceRoles:['STUDENT','FACULTY','ADMIN'],requestId:crypto.randomUUID()});
const draft=ref(blankDraft()),selectedImage=ref(null),imagePreview=ref(''),removeImage=ref(false),imageUrls=ref({}),imageUploadProgress=ref(null);
let refreshTimer;
function clearImages(){for(const url of Object.values(imageUrls.value))URL.revokeObjectURL(url);imageUrls.value={};}
function clearDraft(){if(imagePreview.value)URL.revokeObjectURL(imagePreview.value);imagePreview.value='';selectedImage.value=null;removeImage.value=false;imageUploadProgress.value=null;draft.value=blankDraft();}
function chooseImage(file){if(!file)return;if(imagePreview.value)URL.revokeObjectURL(imagePreview.value);selectedImage.value=file;removeImage.value=false;imagePreview.value=URL.createObjectURL(file);error.value='';}
function clearSelectedImage(){if(imagePreview.value)URL.revokeObjectURL(imagePreview.value);imagePreview.value='';selectedImage.value=null;imageUploadProgress.value=null;}
async function loadImages(){clearImages();const ids=[...new Set([...items.value,...announcements.value,...managed.value].filter(item=>item.hasImage).map(item=>item.resourceType==='announcement'?item.resourceId:item.id))];await Promise.all(ids.map(async id=>{try{const response=await api.get(`/notifications/announcements/${id}/image`,{responseType:'blob'});imageUrls.value[id]=URL.createObjectURL(response.data);}catch{}}));}
async function load(){loading.value=true;error.value='';try{const calls=[api.get('/notifications',{params:{page:page.value,unread:unreadOnly.value}}),api.get('/notifications/announcements')];if(auth.user?.role==='ADMIN')calls.push(api.get('/notifications/announcements/manage',{params:{includeArchived:showArchived.value}}));const [inbox,news,admin]=await Promise.all(calls);items.value=inbox.data.data.rows;total.value=inbox.data.data.total;announcements.value=news.data.data;managed.value=admin?.data.data||[];await loadImages();}catch(e){error.value=e.response?.data?.message||'Could not load notifications.';}finally{loading.value=false;}}
async function markRead(item){try{await api.patch(`/notifications/${item.id}/read`);window.dispatchEvent(new Event('sbaa:notifications'));await load();}catch(e){error.value=e.response?.data?.message||'Could not mark notification read.';}}
async function markAll(){saving.value=true;try{await api.patch('/notifications/read-all');window.dispatchEvent(new Event('sbaa:notifications'));notice.value='All notifications marked as read.';await load();}catch(e){error.value=e.response?.data?.message||'Could not update notifications.';}finally{saving.value=false;}}
async function archive(item){saving.value=true;try{await api.patch(`/notifications/${item.id}/archive`);window.dispatchEvent(new Event('sbaa:notifications'));await load();}catch(e){error.value=e.response?.data?.message||'Could not remove notification.';}finally{saving.value=false;}}
async function clearInbox(){if(!window.confirm('Clear only your inbox? Shared announcements and other users’ messages will remain.'))return;saving.value=true;try{await api.patch('/notifications/archive-all');window.dispatchEvent(new Event('sbaa:notifications'));notice.value='Your inbox was cleared.';page.value=1;await load();}catch(e){error.value=e.response?.data?.message||'Could not clear inbox.';}finally{saving.value=false;}}
async function saveAnnouncement(publishNow=false){
  if(saving.value)return;saving.value=true;error.value='';notice.value='';
  try{
    if(draft.value.id)await api.patch(`/notifications/announcements/${draft.value.id}`,draft.value);
    else{const result=await api.post('/notifications/announcements',{...draft.value,publish:false});draft.value.id=result.data.data.id;}
    if(selectedImage.value){const body=new FormData();body.append('image',selectedImage.value);imageUploadProgress.value=0;await api.put(`/notifications/announcements/${draft.value.id}/image`,body,{timeout:60000,onUploadProgress:event=>{if(event.total)imageUploadProgress.value=Math.min(100,Math.round(event.loaded/event.total*100));}});}
    else if(removeImage.value)await api.delete(`/notifications/announcements/${draft.value.id}/image`);
    if(publishNow)await api.patch(`/notifications/announcements/${draft.value.id}/status`,{status:'PUBLISHED'});
    window.dispatchEvent(new Event('sbaa:notifications'));clearDraft();notice.value=publishNow?'Announcement published and recipients notified.':'Draft saved without notifying recipients.';await load();
  }catch(e){error.value=e.response?.data?.message||'Could not save the announcement. The draft remains available for retry.';}
  finally{saving.value=false;imageUploadProgress.value=null;}
}
function editDraft(item){clearDraft();draft.value={id:item.id,title:item.title,content:item.content,priority:item.priority,audienceRoles:Array.isArray(item.audienceRoles)?item.audienceRoles:JSON.parse(item.audienceRoles||'null')||['STUDENT','FACULTY','ADMIN'],requestId:crypto.randomUUID()};document.getElementById('announcement-editor')?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
async function changeAnnouncement(item,status){if(!window.confirm(`${status==='PUBLISHED'?'Publish':'Withdraw'} “${item.title}”?`))return;saving.value=true;try{await api.patch(`/notifications/announcements/${item.id}/status`,{status});window.dispatchEvent(new Event('sbaa:notifications'));notice.value=status==='PUBLISHED'?'Announcement published.':'Announcement withdrawn.';await load();}catch(e){error.value=e.response?.data?.message||'Could not update announcement.';}finally{saving.value=false;}}
function refreshOnFocus(){if(!document.hidden)load();}
onMounted(()=>{load();document.addEventListener('visibilitychange',refreshOnFocus);refreshTimer=setInterval(refreshOnFocus,60000);});
onBeforeUnmount(()=>{document.removeEventListener('visibilitychange',refreshOnFocus);clearInterval(refreshTimer);clearImages();clearDraft();});
</script>
<template><PortalLayout title="Notifications"><div class="dashboard content-page"><div class="page-heading"><div><p class="eyebrow">INBOX & NEWS</p><h2>Notifications</h2><p>Academic updates sent to your account.</p></div></div><p v-if="error" class="form-error" role="alert">{{error}}</p><p v-if="notice" class="success-message" role="status">{{notice}}</p>
  <section class="panel"><div class="panel-title"><h2>Inbox</h2><div class="inline-actions"><button class="text-button" :disabled="saving" @click="markAll">Mark all read</button><button class="text-button" :disabled="saving||!total" @click="clearInbox">Clear inbox</button></div></div><div class="toolbar"><label class="check-label"><input v-model="unreadOnly" type="checkbox" @change="page=1;load()"/> Unread only</label></div><p v-if="loading" class="empty">Loading notifications…</p><p v-else-if="error" class="empty">Inbox unavailable. Please retry.</p><div v-else-if="items.length" class="record-list"><article v-for="item in items" :key="item.id" class="record-row" :class="{unread:!item.readAt}"><div><span class="eyebrow">{{item.type}} · {{new Date(item.createdAt).toLocaleDateString('en-PH',{timeZone:'Asia/Manila'})}} (Asia/Manila)</span><h3>{{item.title}}</h3><p>{{item.body}}</p><img v-if="item.hasImage&&imageUrls[item.resourceId]" class="announcement-thumb" :src="imageUrls[item.resourceId]" :alt="`Image attached to ${item.title}`"/></div><div class="inline-actions"><button v-if="!item.readAt" class="text-button" :disabled="saving" @click="markRead(item)">Mark read</button><button class="text-button" :disabled="saving" @click="archive(item)">Remove</button></div></article></div><p v-else class="empty">No notifications {{unreadOnly?'unread':''}}. You're all caught up.</p><div class="pagination"><button :disabled="page===1" @click="page--;load()">Previous</button><span>Page {{page}}</span><button :disabled="page*20>=total" @click="page++;load()">Next</button></div></section>
  <section class="panel"><h2>Announcements</h2><div v-if="announcements.length" class="record-list"><article v-for="item in announcements" :key="item.id" class="record-row"><div><span class="eyebrow">{{item.priority}} · {{item.author}}</span><h3>{{item.title}}</h3><p>{{item.content}}</p><img v-if="item.hasImage&&imageUrls[item.id]" class="announcement-full-image" :src="imageUrls[item.id]" :alt="`Image attached to ${item.title}`"/></div></article></div><p v-else class="empty">No published announcements for your account.</p></section>
  <section v-if="auth.user?.role==='ADMIN'" id="announcement-editor" class="panel">
    <h2>{{draft.id?'Edit draft':'Write announcement'}}</h2>
    <form class="stack-form" @submit.prevent="saveAnnouncement(false)">
      <label>Title<input v-model="draft.title" required maxlength="200"/></label>
      <label>Message<textarea v-model="draft.content" required maxlength="10000" rows="4"></textarea></label>
      <label>Priority<select v-model="draft.priority"><option>LOW</option><option>NORMAL</option><option>HIGH</option></select></label>
      <fieldset class="audience-field"><legend>Audience</legend><label v-for="target in ['STUDENT','FACULTY','ADMIN']" :key="target" class="check-label"><input v-model="draft.audienceRoles" type="checkbox" :value="target"/> {{target.toLowerCase()}}</label></fieldset>
      <p class="field-help">Only active users in the selected roles receive a notification when published.</p>
      <FileUpload :file="selectedImage" :preview="imagePreview" :busy="saving" :progress="imageUploadProgress" label="Upload announcement image" hint="JPEG, PNG, or WebP image" :max-mb="5" @select="chooseImage" @remove="clearSelectedImage"/>
      <img v-if="!selectedImage&&!removeImage&&draft.id&&imageUrls[draft.id]" class="announcement-full-image" :src="imageUrls[draft.id]" alt="Current announcement image"/>
      <button v-if="draft.id&&imageUrls[draft.id]&&!removeImage" type="button" class="text-button destructive" :disabled="saving" @click="removeImage=true;clearSelectedImage()">Remove attached image</button>
      <div class="announcement-preview"><p class="eyebrow">RECIPIENT PREVIEW · {{draft.priority}}</p><h3>{{draft.title||'Untitled announcement'}}</h3><p>{{draft.content||'Write your message above.'}}</p><img v-if="imagePreview||(!removeImage&&draft.id&&imageUrls[draft.id])" class="announcement-thumb" :src="imagePreview||imageUrls[draft.id]" alt="Image preview"/></div>
      <div class="inline-actions"><button type="submit" class="secondary-button" :disabled="saving||!draft.audienceRoles.length">{{saving?'Saving…':'Save draft'}}</button><button type="button" class="primary" :disabled="saving||!draft.title.trim()||!draft.content.trim()||!draft.audienceRoles.length" @click="saveAnnouncement(true)">{{saving?'Publishing…':'Publish and notify'}}</button><button v-if="draft.id" type="button" class="text-button" :disabled="saving" @click="clearDraft">New announcement</button></div>
    </form>
  </section>
  <section v-if="auth.user?.role==='ADMIN'" class="panel"><div class="panel-title"><h2>Manage announcements</h2><label class="check-label"><input v-model="showArchived" type="checkbox" @change="load"/> Show archived</label></div><div v-if="managed.length" class="record-list"><article v-for="item in managed" :key="item.id" class="record-row"><div><strong>{{item.title}}</strong><small>{{item.status}} · {{item.priority}}</small></div><div class="inline-actions"><button v-if="item.status==='DRAFT'" class="text-button" @click="editDraft(item)">Edit</button><button v-if="item.status==='DRAFT'" class="text-button" :disabled="saving" @click="changeAnnouncement(item,'PUBLISHED')">Publish</button><button v-if="item.status!=='ARCHIVED'" class="text-button" :disabled="saving" @click="changeAnnouncement(item,'ARCHIVED')">Withdraw</button></div></article></div><p v-else class="empty">No announcements to manage.</p></section>
  </div></PortalLayout></template>
